from fark import satir_farki

def test_satir_farki():
    test_cases = [
        {
            "name": "Basit ortak ve fark",
            "a": ["a", "b", "c"],
            "b": ["a", "c"],
            "expected_len": 3, # ( ,a), (-,b), ( ,c)
            "forbidden": [("+", "any"), ("-", "any")] # Yan yana + sonra - yasak
        },
        {
            "name": "Ekleme ve silme (Sıralama kontrolü)",
            "a": ["1", "2", "3"],
            "b": ["1", "x", "3", "y"],
            "forbidden": [("+", "any"), ("-", "any")] # Art arda + sonra - olmamalı
        },
        {
            "name": "Tamamen farklı",
            "a": ["a", "b"],
            "b": ["c", "d"],
            "expected_len": 4, # (-,a), (-,b), (+,c), (+,d)
        },
        {
            "name": "Aynı listeler",
            "a": ["a", "b"],
            "b": ["a", "b"],
            "expected_len": 2,
        },
        {
            "name": "Karışık (Kural: + sonra - gelmemeli)",
            "a": ["apple", "banana", "cherry"],
            "b": ["apple", "cherry", "date"],
            # a'dan banana silinmeli (-), b'ye date eklenmeli (+)
            # Beklenen: [(' ', 'apple'), ('-', 'banana'), (' ', 'cherry'), ('+', 'date')]
            # Burada bir + (date) ve bir - (banana) var ama sıralama: - sonra +
            # Yani kurala uygun.
        }
    ]

    for case in test_cases:
        result = satir_farki(case["a"], case["b"])
        print(f"Test '{case['name']}':")
        print(f"  Sonuç: {result}")

        # Kural kontrolü: Bir '+' elemanının hemen ardından '-' gelmesin.
        for i in range(len(result) - 1):
            if result[i][0] == "+" and result[i+1][0] == "-":
                print(f"  HATA: Kural ihlali! Art arda '+' ve '-' bulundu: {result[i]} -> {result[i+1]}")
                return False
        print("  Geçti.")

    print("\nTüm testler başarıyla tamamlandı.")
    return True

if __name__ == "__main__":
    test_satir_farki()

